update scheduling
set status = 1
where consultant_id = #{consultantId}

update reservation
set status = 3
where reservation_id = #{reservationId}

mapper.select:
select r.*,u.name as userName,c.role,ha.name as consultantName,d.name as domainName
from reservation r
left join domain d on r.domain_id = d.domain_id
left join user u on r.user_id = u.user_id
left join consultant c on r.consultant_id = c.consultant_id
left join hou_admin ha on c.admin_id = ha.admin_id


        r.user_id = #{reservationDO.userId}


        r.consultant_id = #{reservationDO.consultantId}


        ha.admin_id = #{reservationDO.adminId}


       and u.name like concat('%',#{reservationDO.userName},'%')


       and r.domain_id = #{reservationDO.domainId}


       and ha.name like concat('%',#{reservationDO.consultantName},'%')


       and r.status = #{reservationDO.status}


        and r.orderTime = #{reservationDO.orderTime}


       and r.create_time between #{reservationDO.startDate} and #{reservationDO.endDate}


       and r.problem like concat('%',#{reservationDO.problem},'%')
